CREATE TABLE "user" (
 id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false,
 image text, role text NOT NULL DEFAULT 'reader' CHECK (role IN ('owner','reader')), "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE "session" (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON "session"("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE INDEX account_user_idx ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE user_preferences (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, data jsonb NOT NULL DEFAULT '{"topics":["javascript","typescript","node","react","sql","linux","devops","cloud","integrations","ai"],"difficulty":"intermediate","reviewsEnabled":true,"sessionMinutes":5,"timezone":"Europe/Paris","onboarded":false}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE concepts (key text PRIMARY KEY, objective text NOT NULL, prerequisites text[] NOT NULL DEFAULT '{}');
CREATE TABLE posts (id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('idea','draft','review','published','archived')), concept_key text NOT NULL REFERENCES concepts(key), current_published_version_id uuid, latest_version_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE post_versions (id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts(id), version integer NOT NULL, content jsonb NOT NULL, search_fr tsvector NOT NULL, search_simple tsvector NOT NULL, search_normalized text NOT NULL, author_id text REFERENCES "user"(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, UNIQUE(post_id, version));
ALTER TABLE posts ADD CONSTRAINT posts_published_fk FOREIGN KEY(current_published_version_id) REFERENCES post_versions(id), ADD CONSTRAINT posts_latest_fk FOREIGN KEY(latest_version_id) REFERENCES post_versions(id);
CREATE INDEX post_versions_fr_idx ON post_versions USING gin(search_fr);
CREATE INDEX post_versions_simple_idx ON post_versions USING gin(search_simple);
CREATE INDEX posts_status_idx ON posts(status, updated_at);
CREATE INDEX posts_concept_idx ON posts(concept_key);
CREATE TABLE saved_posts (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES posts(id), saved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,post_id));
CREATE INDEX saved_posts_date_idx ON saved_posts(user_id,saved_at DESC,post_id);
CREATE TABLE post_feedback (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES posts(id), kind text NOT NULL CHECK(kind IN ('known','more','less')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,post_id));
CREATE TABLE feed_sessions (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, seed text NOT NULL, ranking_version integer NOT NULL, post_ids uuid[] NOT NULL, served_count integer NOT NULL DEFAULT 0, question_count integer NOT NULL DEFAULT 0, last_question_at_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), last_active_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX feed_sessions_user_idx ON feed_sessions(user_id,last_active_at DESC);
CREATE TABLE exposures (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES posts(id), session_id uuid NOT NULL REFERENCES feed_sessions(id) ON DELETE CASCADE, event_id uuid NOT NULL, visible_ms integer NOT NULL CHECK(visible_ms>=0), ratio real NOT NULL CHECK(ratio BETWEEN 0 AND 1), qualified boolean NOT NULL, slides jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_id), UNIQUE(user_id,session_id,post_id));
CREATE INDEX exposures_user_post_idx ON exposures(user_id,post_id,created_at DESC);
CREATE TABLE question_versions (id uuid PRIMARY KEY, concept_key text NOT NULL REFERENCES concepts(key), version integer NOT NULL, prompt text NOT NULL, choices jsonb NOT NULL, correct_choice_id text NOT NULL, explanation text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(concept_key,version));
CREATE TABLE learning_states (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, concept_key text NOT NULL REFERENCES concepts(key), stage_index integer NOT NULL DEFAULT 0 CHECK(stage_index BETWEEN 0 AND 6), due_at timestamptz NOT NULL DEFAULT now()+interval '1 day', last_answered_at timestamptz, failures integer NOT NULL DEFAULT 0, algorithm_version integer NOT NULL DEFAULT 1, lock_version integer NOT NULL DEFAULT 0, last_skipped_at timestamptz, PRIMARY KEY(user_id,concept_key));
CREATE INDEX learning_due_idx ON learning_states(user_id,due_at);
CREATE TABLE review_opportunities (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, concept_key text NOT NULL REFERENCES concepts(key), due_at timestamptz NOT NULL, question_id uuid NOT NULL REFERENCES question_versions(id), choice_order jsonb NOT NULL, feed_session_id uuid REFERENCES feed_sessions(id) ON DELETE SET NULL, effective_attempt_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,concept_key,due_at));
CREATE TABLE review_presentations (session_id uuid NOT NULL REFERENCES feed_sessions(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES question_versions(id), opportunity_id uuid NOT NULL REFERENCES review_opportunities(id) ON DELETE CASCADE, PRIMARY KEY(session_id,question_id));
CREATE TABLE question_attempts (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES question_versions(id), concept_key text NOT NULL REFERENCES concepts(key), opportunity_id uuid REFERENCES review_opportunities(id) ON DELETE CASCADE, mode text NOT NULL CHECK(mode IN ('immediate','review')), choice_id text, choice_order jsonb NOT NULL, correct boolean, action text NOT NULL CHECK(action IN ('answer','skip')), guessed boolean, effective boolean NOT NULL DEFAULT false, confidence_submitted boolean NOT NULL DEFAULT false, result jsonb NOT NULL, idempotency_key text NOT NULL, answered_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE INDEX question_attempts_user_idx ON question_attempts(user_id,concept_key,answered_at DESC);
ALTER TABLE review_opportunities ADD CONSTRAINT opportunities_effective_fk FOREIGN KEY(effective_attempt_id) REFERENCES question_attempts(id) ON DELETE SET NULL;
CREATE TABLE content_reports (id uuid PRIMARY KEY, user_id text REFERENCES "user"(id) ON DELETE SET NULL, post_version_id uuid NOT NULL REFERENCES post_versions(id), reason text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor_id text REFERENCES "user"(id) ON DELETE SET NULL, action text NOT NULL, target_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
